using MiniStore.Application.DTOs.Settings;

namespace MiniStore.Application.Services;

public sealed class WorkflowCatalogService
{
    public WorkflowCatalogPageDto GetAll()
    {
        var purchasing = GetPurchasing();
        return new WorkflowCatalogPageDto
        {
            ModuleName = "Complete ERP workflow catalog",
            Purpose = "A role-aware operating guide covering setup, customers, sales, purchasing, inventory, accounting, administration and analytics from preparation through review.",
            Steps =
            [
                ..SetupSteps(),
                ..CustomerSteps(),
                ..SalesSteps(),
                ..purchasing.Steps,
                ..InventorySteps(),
                ..AccountingSteps(),
                ..AnalyticsSteps()
            ]
        };
    }

    public WorkflowCatalogPageDto GetPurchasing() => new()
    {
        ModuleName = "Purchasing workflow catalog",
        Purpose = "The recommended administrative and accounting sequence from demand identification through payment, return, closure and management review.",
        Steps =
        [
            Step(1,"Setup","Prepare purchasing and accounting foundations","System administrator and chief accountant","Finance manager","Configure suppliers, products, units, warehouses, document numbers, taxes, currencies, approval rules and posting accounts before operational purchasing begins.","Configuration must be approved before transactions; master data and posting accounts are not completed inside operational documents.","Required settings and master data are active and reviewed.","Settings","Index","Administration.Access"),
            Step(2,"Demand","Create the purchase request","Requesting department or warehouse planner","Department manager","Record the actual need, warehouse, required date, quantities, business justification and suggested supplier when known.","The requester documents the need but should not approve their own request.","A draft purchase request exists with complete lines and justification.","PurchaseRequests","Create","PurchaseRequests.Create"),
            Step(3,"Demand","Submit the purchase request","Requester","Department manager or budget owner","Review the draft for completeness, then submit it into the configured approval sequence.","Submission freezes the request for approval and preserves who requested what and when.","The request status is Submitted and an approval instance exists.","PurchaseRequests","Index","PurchaseRequests.Submit"),
            Step(4,"Approval","Approve or reject the request","Department manager or budget owner","Procurement manager","Confirm business need, budget responsibility and requested timing; reject with a clear reason when the request is not justified.","Approval must be independent from request preparation whenever staffing permits.","The request is Approved or Rejected with actor, time and reason evidence.","PurchaseRequests","Index","PurchaseRequests.Approve"),
            Step(5,"Sourcing","Prepare and send the request for quotation","Procurement officer","Procurement manager","Create sourcing from an approved request, select eligible suppliers, attach specifications and send the invitation.","Competitive sourcing and equal supplier information reduce bias and preserve an audit trail.","The sourcing event is Sent and supplier invitations are recorded.","PurchaseSourcing","Index","PurchaseSourcing.Create"),
            Step(6,"Sourcing","Record supplier quotations","Procurement officer","Procurement manager","Enter each supplier response exactly as received, including validity, lead time, currency, price, discount, tax and payment terms.","Supplier offers are evidence; do not overwrite one supplier's commercial terms with another supplier's data.","Submitted quotations exist for the invited suppliers.","SupplierQuotations","Comparison","SupplierQuotations.Create"),
            Step(7,"Award","Compare and award quotations","Procurement manager or authorized buyer","Budget owner","Compare price, company-currency value, delivery, quality and commercial terms; split quantities only when justified and record the award reason.","The lowest price is not automatically the best value; the award decision must be explainable and traceable.","Award allocations equal the required quantity and the decision reason is saved.","SupplierQuotations","Comparison","SupplierQuotations.Award"),
            Step(8,"Commitment","Create and approve the purchase order","Authorized buyer","Procurement manager or budget owner","Create the purchase order from the award, verify supplier, warehouse, quantities, prices, taxes, currency, expected date and fulfillment route, then approve it.","A purchase order is the commercial commitment; it must not be created from an unapproved demand or changed silently after approval.","The purchase order is Approved with frozen commercial snapshots.","PurchaseOrders","Index","PurchaseOrders.Approve"),
            Step(9,"Commitment","Confirm the order with the supplier","Buyer or procurement officer","Procurement manager","Send the approved order, obtain supplier confirmation and record the confirmed date and supplier reference.","Supplier acknowledgement is operational evidence and must remain distinct from internal approval.","The order is Confirmed and supplier communication or portal evidence is retained.","PurchaseOrders","Index","PurchaseOrders.Confirm"),
            Step(10,"Receipt","Receive and inspect goods","Warehouse receiver and quality inspector","Warehouse supervisor","Receive only against the confirmed order, record actual quantity and tracking data, inspect when required, then put away approved goods.","The buyer should not be the sole receiver; physical receipt must be independent from ordering and invoicing.","A posted goods receipt and any quality or putaway evidence exist.","GoodsReceipts","Index","GoodsReceipts.Create"),
            Step(11,"Invoice","Enter the supplier invoice","Accounts payable accountant","Senior accountant","Create the vendor bill from the purchase order and receipt or service evidence; record the supplier invoice number, date, currency and allocations without posting immediately.","Invoice entry records a claim but does not by itself prove receipt, price correctness or authorization to pay.","A Draft vendor bill exists with source allocations and attachments.","VendorBills","Index","VendorBills.Create"),
            Step(12,"Invoice","Perform three-way matching","Accounts payable accountant","Finance manager","Compare purchase order, goods receipt or service completion, and vendor bill quantities and prices; investigate every exception.","Quantity and price differences require evidence. Overrides must be exceptional, permission-controlled and reasoned.","A match run exists; exceptions are resolved or overridden with a documented reason.","VendorBills","Index","VendorBills.View"),
            Step(13,"Accounting","Approve and post the vendor bill","Senior accountant","Finance manager or financial controller","Approve only after successful matching, then post within an open fiscal period using configured payable, tax, inventory, expense, GRNI and variance accounts.","Approval and posting establish the accounting liability; the preparer and approver should be separated when possible.","The vendor bill is Posted and a balanced journal entry is linked.","VendorBills","Index","VendorBills.Post"),
            Step(14,"Settlement","Prepare and post supplier payment","Treasury accountant or cashier","Finance manager","Select posted outstanding bills, verify due amounts, payment method, currency, bank or cash evidence and external reference, then post the payment.","Payment custody should be separate from invoice entry and approval; never pay an unposted or unsupported bill.","A posted supplier payment reduces the selected payable balances.","SupplierPayments","Index","SupplierPayments.Create"),
            Step(15,"Exception","Return rejected goods","Warehouse supervisor","Procurement officer and accounts payable accountant","When accepted goods must be returned, create a receipt-based return with exact quantities, tracking identities and reason.","A physical return reverses inventory first and must remain linked to the original receipt.","A posted goods receipt return and inventory/accounting reversal evidence exist.","GoodsReceiptReturns","Index","GoodsReceiptReturns.Create",true),
            Step(16,"Exception","Record the supplier credit note","Accounts payable accountant","Senior accountant","Create the credit note from billed returned quantities and verify its link to the original bill, receipt and purchase order.","A supplier credit note reduces the liability and must not be replaced by editing the posted invoice.","A posted supplier credit note is linked to the billed return.","SupplierCreditNotes","Index","SupplierCreditNotes.Create",true),
            Step(17,"Closure","Close the purchase order","Buyer or procurement manager","Procurement manager","Close automatically after all required receipt, service, delivery and billing quantities finish; otherwise close the remaining quantity only with a documented reason.","Closure is a control decision, not deletion. Remaining commitments must be explained and retained.","The order status is Closed and its closure type, actor and reason are visible.","PurchaseOrders","Index","PurchaseOrders.Close"),
            Step(18,"Reconciliation","Reconcile purchasing with accounting","Chief accountant or financial controller","Finance manager","Review inventory valuation, GRNI, vendor bills, payments, credit notes and reversals against the general ledger; resolve differences before period close.","Subledger totals must reconcile to control accounts and every difference must lead to source evidence.","Inventory and GRNI reconciliation show no unexplained exceptions.","PurchaseAccountingReconciliation","Index","PurchaseAccountingReconciliation.View"),
            Step(19,"Management review","Review supplier and purchasing performance","Procurement manager and financial controller","General manager","Review spend, delays, confirmations, lead time, price variance, returns, buyer workload and open matching exceptions, then assign corrective actions.","Management indicators support decisions only when their period, source and calculation are understood.","The review is based on traceable KPI sources and open exceptions have owners.","PurchaseAnalytics","Index","PurchaseAnalytics.View")
        ]
    };

    private static List<WorkflowCatalogStepDto> SetupSteps() =>
    [
        ModuleStep("Setup and administration",1,"Company setup","Complete guided company setup","Company owner","System administrator","Choose the business profile, country, currency, language and starter configuration before operational work begins.","Foundation settings must be reviewed before users create transactions.","Company setup is completed and the tenant dashboard is available.","CompanyOnboarding","Index","Administration.Access"),
        ModuleStep("Setup and administration",2,"Identity","Define organization identity","System administrator","Company owner","Enter legal and trade names, registrations, contacts, addresses, logo and reusable document fields.","Identity is maintained once and reused by every supported document.","The organization identity screen contains reviewed bilingual details.","Settings","OrganizationIdentity","Administration.Access"),
        ModuleStep("Setup and administration",3,"Financial foundation","Prepare accounts, branches, taxes and payment methods","Chief accountant","Finance manager","Create the chart of accounts, operating branches, tax rates and settlement methods before posting.","Posting authorities must reference approved master data rather than free text.","Accounts, branches, taxes and payment methods are active.","Accounts","Index","Settings.View"),
        ModuleStep("Setup and administration",4,"Inventory foundation","Prepare products, units, warehouses and locations","Inventory manager","Operations manager","Create products, managed units, warehouses, storage locations and tracking policies.","Product and warehouse identities are controlled master data.","Active products and named storage destinations are ready for use.","Products","Index","Products.View"),
        ModuleStep("Setup and administration",5,"Document control","Configure numbering and document designs","System administrator","Finance manager","Configure document sequences, organization branding and active document designs for each document type.","Document numbers and active layouts must remain versioned and auditable.","Each required document type has a valid sequence and active default design.","DocumentDesigns","Index","Administration.Access"),
        ModuleStep("Setup and administration",6,"Access control","Create users, roles and permissions","Company owner","Security administrator","Create users and assign the minimum roles and permissions needed for their duties.","Least privilege and separation of duties reduce unauthorized operations.","Every active user has an approved role assignment.","Users","Index","Users.View"),
        ModuleStep("Setup and administration",7,"Control period","Open fiscal periods and operating policies","Chief accountant","Finance manager","Create fiscal periods and approve sales, purchasing, inventory and accounting policies.","Transactions must use approved policies and an open accounting period.","The current period is open and policy settings are reviewed.","Settings","FiscalPeriods","Administration.Access"),
        ModuleStep("Setup and administration",8,"Audit","Review audit and security evidence","Security administrator","Company owner","Review sensitive configuration changes, denied actions, exports and integration activity regularly.","Audit evidence is read-only, permission-controlled and retained by policy.","Open audit exceptions have an owner and resolution.","AuditEvents","Index","AuditEvents.View")
    ];

    private static List<WorkflowCatalogStepDto> CustomerSteps() =>
    [
        ModuleStep("Customer management",1,"Master data","Create the customer profile","Sales administrator","Finance reviewer","Record the customer code, identity, language, contacts and tax information.","A customer must have one stable tenant-owned identity.","The active customer profile is complete.","Customers","Create","Customers.Create"),
        ModuleStep("Customer management",2,"Communication","Add customer contacts and addresses","Sales administrator","Customer account owner","Add active contacts plus billing and shipping addresses with clear defaults.","Contact and address history is archived rather than deleted.","Required default contacts and addresses are available.","Customers","Index","Customers.Edit"),
        ModuleStep("Customer management",3,"Credit setup","Assign receivable and commercial defaults","Credit controller","Finance manager","Set payment terms, receivable policy, currency, tax exemption and default price list.","Credit and accounting defaults are prospective and must not rewrite historical documents.","Receivable and commercial defaults are approved.","Customers","Index","Customers.Edit"),
        ModuleStep("Customer management",4,"Review","Review customer exposure and activity","Credit controller","Sales manager","Review open invoices, overdue exposure, quotations, orders, payments and credits before new commitments.","Credit decisions use current authoritative balances.","Exceptions are resolved or routed to approval.","AnalyticsCenter","Index","AnalyticsCenter.View"),
        ModuleStep("Customer management",5,"Lifecycle","Archive or restore the customer","Sales administrator","Finance reviewer","Archive inactive customers without deleting history; restore only after review.","Archived customers remain available to historical documents but not new sales.","The lifecycle state and actor evidence are retained.","Customers","Index","Customers.Archive",true)
    ];

    private static List<WorkflowCatalogStepDto> SalesSteps() =>
    [
        ModuleStep("Sales and receivables",1,"Pricing","Maintain sales price lists and rules","Sales manager","Finance manager","Define dated customer, product, category, unit and quantity pricing rules.","The server recalculates prices; users do not supply authoritative prices.","Active rules have clear priority, currency and validity.","SalesPriceLists","Index","SalesPricing.View"),
        ModuleStep("Sales and receivables",2,"Quotation setup","Prepare quotation templates","Sales administrator","Sales manager","Create and activate reusable versioned content, options, quantities and document design choices.","Active template versions are immutable and historical use is frozen.","An approved active template is available.","SalesQuotationTemplates","Index","SalesQuotationTemplates.View"),
        ModuleStep("Sales and receivables",3,"Quotation","Create and send the quotation","Sales representative","Sales manager","Select the customer and template, review repriced lines, validity, taxes and terms, then send.","A quotation creates no inventory or accounting effect.","The quotation is Sent with frozen commercial and document evidence.","SalesQuotations","Index","SalesQuotations.Create"),
        ModuleStep("Sales and receivables",4,"Acceptance","Record the customer decision","Sales representative","Sales manager","Record acceptance, rejection, expiry or cancellation using the actual customer decision.","Lifecycle decisions are append-only and cannot be inferred from later documents.","The quotation has a final traceable status.","SalesQuotations","Index","SalesQuotations.Accept"),
        ModuleStep("Sales and receivables",5,"Order","Create and confirm the sales order","Sales representative","Sales manager or configured approver","Convert an accepted quotation once, evaluate controls and confirm only after required approvals.","Confirmation creates a commitment but no stock or journal entry.","The order is Confirmed with approval evidence.","SalesOrders","Index","SalesOrders.Confirm"),
        ModuleStep("Sales and receivables",6,"Reservation","Reserve inventory for the order","Inventory planner","Warehouse supervisor","Reserve available stock by warehouse and location using the approved shortage policy.","Reservation changes availability but not on-hand quantity or accounting.","Active reservations cover the intended order quantities.","SalesOrders","Index","SalesOrders.Reserve"),
        ModuleStep("Sales and receivables",7,"Delivery","Prepare and post delivery","Warehouse picker","Warehouse supervisor","Prepare the delivery from active reservations, allocate tracking identities and post physical issue.","Delivery owns inventory issue and COGS; it must use exact reserved sources.","A Posted delivery is linked to stock movement and COGS journal.","SalesDeliveries","Index","SalesDeliveries.Post"),
        ModuleStep("Sales and receivables",8,"Invoicing","Create, approve and post the customer invoice","Billing accountant","Finance manager","Create from eligible order or delivery quantities, approve and post within an open period.","Posting establishes receivable, revenue and tax without changing inventory.","The invoice is Posted with a balanced journal.","CustomerInvoices","Index","CustomerInvoices.Post"),
        ModuleStep("Sales and receivables",9,"Collection","Record and allocate customer payment","Receivables accountant","Treasury supervisor","Allocate a received payment to posted invoices using the actual method, currency and reference.","Collection custody and invoice preparation should be separated.","A Posted payment reduces the selected invoice balances.","CustomerPayments","Index","CustomerPayments.Create"),
        ModuleStep("Sales and receivables",10,"Return authorization","Authorize a customer return","Customer service","Sales manager","Create, submit and approve the request against exact delivered quantities.","Authorization alone does not change stock, accounting or customer balance.","An Approved return request records the decision trail.","CustomerReturnRequests","Index","CustomerReturnRequests.Approve",true),
        ModuleStep("Sales and receivables",11,"Return receipt","Receive, inspect and post disposition","Warehouse receiver","Warehouse supervisor","Receive approved quantities, verify tracking, inspect and post Restock, Quarantine, Reject or Destroy disposition.","Physical custody and financial credit remain separate authorities.","Receipt, inspection and disposition evidence are complete.","CustomerReturnReceipts","Index","CustomerReturnReceipts.PostDisposition",true),
        ModuleStep("Sales and receivables",12,"Customer credit","Issue the customer credit note","Receivables accountant","Finance manager","Credit only eligible posted invoice and returned quantities; handle cash refund separately.","Credit reverses receivable, revenue and tax without repeating inventory.","A Posted customer credit note is linked to its invoice and return.","CustomerCreditNotes","Index","CustomerCreditNotes.Create",true)
    ];

    private static List<WorkflowCatalogStepDto> InventorySteps() =>
    [
        ModuleStep("Inventory and warehouses",1,"Structure","Maintain warehouses and storage locations","Inventory manager","Operations manager","Define named warehouses, hierarchical locations and receive, pick and reserve capabilities.","Users select business names while internal IDs remain hidden.","Every active warehouse has valid operating locations.","WarehouseLocations","Index","Warehouses.View"),
        ModuleStep("Inventory and warehouses",2,"Opening control","Establish stock and tracking identities","Inventory accountant","Inventory manager","Create approved opening balances and allocate required lot or serial identities.","Opening quantities must reconcile to detailed locations and tracking.","On-hand, location and tracking totals agree.","InventoryTracking","Index","InventoryTracking.Open"),
        ModuleStep("Inventory and warehouses",3,"Movement","Move stock between locations","Warehouse operator","Warehouse supervisor","Record internal movements with source, destination, quantity and reference.","Every physical move must create immutable movement evidence.","Location balances and movement history are updated.","LocationMovements","Index","LocationMovements.Create"),
        ModuleStep("Inventory and warehouses",4,"Transfer","Execute warehouse transfer","Warehouse dispatcher","Receiving warehouse supervisor","Create, submit, approve, dispatch and receive the transfer through its controlled stages.","In-transit custody must remain visible and quantities cannot be received twice.","The transfer is Posted or closed with complete movement evidence.","StockTransfers","Index","StockTransfers.View"),
        ModuleStep("Inventory and warehouses",5,"Counting","Count and adjust inventory","Independent counter","Inventory manager","Create the count, record actual quantities, approve differences and post the adjustment.","The counter should not approve their own material variance.","A Posted adjustment explains every difference.","InventoryAdjustments","Index","InventoryAdjustments.View"),
        ModuleStep("Inventory and warehouses",6,"Availability","Monitor balances and reservations","Inventory planner","Operations manager","Review on-hand, reserved, available and unassigned quantities by product, warehouse and location.","Availability is derived from authoritative balances and active reservations.","Negative or unassigned exceptions have an owner.","InventoryBalances","Index","InventoryBalances.View"),
        ModuleStep("Inventory and warehouses",7,"Replenishment","Review replenishment suggestions","Inventory planner","Procurement manager","Review min/max, demand and seasonality suggestions before creating transfers or purchase demand.","Automation proposes actions but approved workflows execute them.","Accepted suggestions link to their generated demand.","Replenishment","Index","Inventory.Replenishment.View"),
        ModuleStep("Inventory and warehouses",8,"Quality","Manage quarantine and recalls","Quality manager","Operations manager","Quarantine suspect identities, release only after evidence and execute recalls with communication logs.","Tracked safety decisions must be identity-specific and auditable.","Every quarantine or recall has a resolved state and evidence.","InventoryTracking","Index","InventoryTracking.ManageQuarantine",true),
        ModuleStep("Inventory and warehouses",9,"Reconciliation","Reconcile inventory authorities","Inventory accountant","Chief accountant","Compare product stock, location balances, tracking, movements and inventory GL control accounts.","Operational and financial inventory must reconcile before period close.","No unexplained quantity or value differences remain.","InventoryReconciliation","Index","InventoryReconciliation.View")
    ];

    private static List<WorkflowCatalogStepDto> AccountingSteps() =>
    [
        ModuleStep("Accounting and close",1,"Configuration","Approve posting accounts and policies","Chief accountant","Finance manager","Map inventory, revenue, discount, tax, receivable, payable, GRNI, variance and settlement accounts.","Operational services post only through approved accounting configuration.","All required posting accounts are valid and active.","Settings","Accounting","Administration.Access"),
        ModuleStep("Accounting and close",2,"Period control","Manage fiscal periods","Chief accountant","Finance manager","Open the working period, soft close for review and close only after reconciliations.","Closed periods reject new operational postings.","Period status changes retain actor, time and reason.","Settings","FiscalPeriods","Administration.Access"),
        ModuleStep("Accounting and close",3,"Journal review","Review source-linked journal entries","General accountant","Chief accountant","Review balanced entries, sources, branches, warehouses, currencies and reversal links from the governed analytics workspace and open their source evidence.","Posted journals are corrected by controlled reversal, never silent editing.","Every sampled entry is balanced and traceable to its source.","AnalyticsCenter","Index","AnalyticsCenter.View"),
        ModuleStep("Accounting and close",4,"Receivables","Reconcile customer receivables","Receivables accountant","Chief accountant","Reconcile invoices, payments, credits and reversals to the receivable control accounts.","Customer balances are derived from posted allocations and credits.","Customer subledger equals the general ledger control balance.","AnalyticsCenter","Index","AnalyticsCenter.View"),
        ModuleStep("Accounting and close",5,"Payables","Reconcile supplier payables and GRNI","Payables accountant","Chief accountant","Reconcile receipts, vendor bills, payments, returns, credits and GRNI.","Unbilled receipts and supplier liabilities remain distinct.","Payables and GRNI reports have no unexplained differences.","PurchaseAccountingReconciliation","Index","PurchaseAccountingReconciliation.View"),
        ModuleStep("Accounting and close",6,"Close","Perform management review and close","Chief accountant","Finance manager","Resolve exceptions, review taxes and margins, retain evidence and close the period.","Period close follows reconciliation and approval, not calendar date alone.","The period is Closed with approved review evidence.","Settings","FiscalPeriods","Administration.Access")
    ];

    private static List<WorkflowCatalogStepDto> AnalyticsSteps() =>
    [
        ModuleStep("Analytics and management review",1,"Workspace","Create governed analytics workspaces","Business analyst","Module manager","Choose an authorized provider, period, dimension, comparison and reusable widgets.","Analytics remain read-only and tenant-filtered through registered providers.","A personal or shared workspace has approved content.","AnalyticsCenter","Create","AnalyticsCenter.Customize"),
        ModuleStep("Analytics and management review",2,"Review","Review operational and financial KPIs","Module manager","General manager","Review definitions, sources, trends, targets and exceptions before acting.","A KPI supports decisions only when its scope and calculation are understood.","Exceptions have owners and documented follow-up.","AnalyticsCenter","Index","AnalyticsCenter.View"),
        ModuleStep("Analytics and management review",3,"Audit","Reconcile decisions to source documents","Internal reviewer","General manager","Open source documents behind material indicators and verify the decision trail.","Dashboards do not replace accounting or operational source evidence.","Material decisions are traceable to authorized records.","AuditEvents","Index","AuditEvents.View")
    ];

    private static WorkflowCatalogStepDto Step(int number,string phase,string title,string owner,string reviewer,string instructions,string principle,string evidence,string controller,string action,string permission,bool conditional=false) =>
        ModuleStep("Purchasing and payables",number,phase,title,owner,reviewer,instructions,principle,evidence,controller,action,permission,conditional);

    private static WorkflowCatalogStepDto ModuleStep(string module,int number,string phase,string title,string owner,string reviewer,string instructions,string principle,string evidence,string controller,string action,string permission,bool conditional=false) =>
        new(module,number,phase,title,owner,reviewer,instructions,principle,evidence,controller,action,permission,conditional);
}
